const source=fs.readFileSync(new URL('../baka-helper.user.js',import.meta.url),'utf8').replace('  if(document.readyState===\'loading\')','  window.__BANK={bankQuestion,bankParseQuestion,bankKey,bankLookup,bankEntries,collectBank,bankExport,bankImport,bankBeforeAdvance,explicitCorrect,startBankScan,stopBankScan,bankScanTick,restoreBankScan};\n  if(document.readyState===\'loading\')');
const hook=`window.__T={S,cfg,providers,profile,parseQuestion,questionRoots,filled,checked,validateAnswer,fill,answer,makeRequest,decode,taskDone,advance,firstUnfinished,pageKey,chapterId,currentEpoch,tick,readTick,readIdentity,pause,start,doHomework,mount,models,readerLinks,handleSubmission,ui,supportsVision,setFullAuto,responseTimeout,cardIdentity,deferQuestion,recoveryIO,readRecovery,recoverPage,recoveryBoot,recoveryTick,recoveryContext,pageError,safeCourseURL,rememberReturn,videoWatchdog,playVideo,loadQuestionFonts,captureStage,fault,progress,readFlow,flowBoot,continuityTick,recoverContinuous,flowURL,readerNext,readerScroller,waitReader,acquire,ownsLease,renewLease,release,leavePage,restorePage,loginForm,saveLoginAccount,clearLoginAccount,loginTick,authTick,readAuth,rememberSession,makeAuthRequest,suspendForAuth,cancelAuthResume,mountLogin,redact};return;\n`;
async function setup({titleOnly=false,video=false,complete=false,moreVideos=false,quiz=false,reader=false,overview=false,login=false,ownerId="test-tab"}={}){
  const dom=new JSDOM(reader?`<body><div id="ztMainBoxFocus"></div><p>阅读正文</p><a class="nodeItem" href="?courseId=book&knowledgeId=second">下一页</a></body>`:`<body><div id="mainid"></div><div id="dct1" class="active" title="${quiz?'章节测验':video?'视频':''}" cardid="one"></div><div id="dct2" title="章节测验" cardid="two"></div>${titleOnly?'':'<iframe id="iframe"></iframe>'}<div id="content1"><div id="cur100" class="posCatalog_active"><span class="posCatalog_name" onclick="" title="当前">当前</span></div><div id="cur101"><span class="posCatalog_name" onclick="" title="已完成">已完成</span><span class="icon_Completed"></span></div><div id="cur102"><span class="posCatalog_name" onclick="" title="未完成">未完成</span><span class="orangeNew">2</span></div></div></body>`,{url:reader?'https://mooc1.chaoxing.com/mooc-ans/ztnodedetailcontroller/visitnodedetail?courseId=book&knowledgeId=first':'https://mooc1.chaoxing.com/mycourse/studentstudy?courseId=course&chapterId=100',runScripts:'outside-only',pretendToBeVisual:true});
  if(overview)dom.reconfigure({url:'https://mooc2-ans.chaoxing.com/mooc2-ans/mycourse/stu?courseid=course'});
  if(login){dom.reconfigure({url:"https://v8.chaoxing.com/"});dom.window.document.body.innerHTML='<form id="loginForm" method="post"><input id="uunnmm" name="uname" type="text"><input id="pwd" name="pwd" type="password"><input id="login" type="button" value="登录"></form><div id="captcha" hidden>请完成安全验证 向右拖动滑块填充拼图</div>';}
  const w=dom.window,store=new Map();w.unsafeWindow=w;
  w.GM_getValue=(k,d)=>store.has(k)?store.get(k):d;w.GM_setValue=(k,v)=>store.set(k,v);
  w.GM_getTab=fn=>fn({cirnoId:ownerId});w.GM_saveTab=()=>{};w.GM_openInTab=()=>{};
  w.GM_xmlhttpRequest=()=>{throw Error('Unexpected API call');};w.setInterval=()=>0;
  function visible(d){d.defaultView.HTMLElement.prototype.getClientRects=function(){let el=this;while(el){if(el.hidden||el.style?.display==='none')return [];el=el.parentElement;}return [{}];};}
  visible(w.document);let plays=0,clicks=[];
  const f=w.document.querySelector('#iframe');
  if(f){
    Object.defineProperty(f,'src',{get:()=>`https://mooc1.chaoxing.com/mooc-ans/knowledge/cards?courseid=course&knowledgeid=100&num=0`});
    f.contentDocument.body.innerHTML='<div id="pageDiv"></div>';Object.defineProperty(f.contentDocument,'readyState',{get:()=> 'complete'});visible(f.contentDocument);
    if(video){
      f.contentDocument.querySelector('#pageDiv').innerHTML=`<div class="ans-attach-ct ${complete?'ans-job-finished':''}"><div class="ans-job-icon ans-job-video" aria-label="任务点${complete?'已':'未'}完成"></div><iframe src="/ananas/modules/video/index.html"></iframe></div>`+(moreVideos?'<div class="ans-attach-ct"><div class="ans-job-icon ans-job-video" aria-label="任务点未完成"></div><iframe src="/ananas/modules/video/index.html"></iframe></div>':'');
      for(const vf of f.contentDocument.querySelectorAll('iframe')){
        vf.contentDocument.open();vf.contentDocument.write('<!doctype html><html><body><video></video></body></html>');vf.contentDocument.close();Object.defineProperty(vf.contentDocument,'readyState',{get:()=> 'complete'});visible(vf.contentDocument);
        const v=vf.contentDocument.querySelector('video');v.play=async()=>{plays++;};v.pause=()=>{};
      }
    }
  }
  for(const el of w.document.querySelectorAll('.posCatalog_name,[id^="dct"],a.nodeItem'))el.addEventListener('click',e=>{e.preventDefault();clicks.push(el.closest('[id^="cur"]')?.id||el.id||'next');});
  const injection=source.replace("  if(document.readyState==='loading')",hook+"  if(document.readyState==='loading')");
  await w.eval(injection);const T=w.__T;T.S.started=true;T.S.key=T.pageKey();T.S.changed=Date.now()-30000;store.set('cirno.lock.v5',{owner:ownerId,at:Date.now()});
  return {w,T,store,card:f?.contentDocument,counts:()=>({plays,clicks}),close:()=>w.close(),visible};
}
function question(d,{multi=false,encrypted=false,filled=false}={}){
  const root=d.createElement('div');root.className='TiMu';root.innerHTML=`<div class="Zy_TItle"><div class="fontLabel ${encrypted?'font-cxsecret':''}">【${multi?'多':'单'}选题】测试题</div></div><ul class="Zy_ulTop">${['A','B','C'].map(l=>`<li role="${multi?'checkbox':'radio'}" qid="100"><span class="num_option ${filled&&l==='A'?'check_answer':''}" data="${l}">${l}</span><a>选项 ${l}</a></li>`).join('')}</ul><input type="hidden" id="answer100" value="${filled?'A':''}">`;d.body.append(root);
  root.querySelectorAll('li').forEach(li=>li.onclick=()=>{const s=li.querySelector('span');if(!multi)root.querySelectorAll('.num_option').forEach(x=>x.classList.remove('check_answer'));s.classList.toggle('check_answer');root.querySelector('input').value=[...root.querySelectorAll('.check_answer')].map(x=>x.getAttribute('data')).join('');});
  return root;
}
