function judgeFixture(x,index=3){
  const samples=JSON.parse(fs.readFileSync(new URL('judge-fixture.json',import.meta.url),'utf8'));x.card.body.innerHTML=samples[index];const root=x.card.querySelector('.TiMu');
  for(const li of root.querySelectorAll('li'))li.onclick=()=>{const multi=li.getAttribute('qtype')==='1',cls=multi?'check_answer_dx':'check_answer',mark=li.querySelector('.num_option,.num_option_dx'),was=mark.classList.contains(cls);if(!multi)for(const item of root.querySelectorAll('li')){item.setAttribute('aria-checked','false');item.querySelector('span').classList.remove(cls);}mark.classList.toggle(cls,!was);li.setAttribute('aria-checked',String(!was));root.querySelector('input').value=[...root.querySelectorAll('.'+cls)].map(e=>e.getAttribute('data')).join('');};
  return root;
}
