function networkFixture(x,failures){
  x.T.cfg.provider='deepseek';x.T.cfg.profiles.deepseek={key:'fake-test-key'};let calls=0;
  const native=x.w.setTimeout.bind(x.w);x.w.setTimeout=(fn,ms,...args)=>native(fn,ms===1000?1:ms,...args);
  x.w.GM_xmlhttpRequest=o=>{const index=calls++;setTimeout(()=>{const f=failures[index];if(f==='network')o.onerror();else if(f==='timeout')o.ontimeout();else if(f)o.onload({status:f,responseText:'{}'});else o.onload({status:200,responseText:JSON.stringify({choices:[{message:{content:JSON.stringify({choices:['B'],answer:'B'})}}]})});},0);return {abort:()=>o.onabort()};};return ()=>calls;
}
