await test('API transient retries stop after three attempts',async()=>{const x=await setup(),q=x.T.parseQuestion(question(x.card)),calls=networkFixture(x,[503,'timeout','network']);await assert.rejects(x.T.answer(q,x.T.currentEpoch()),/API 网络连接失败/);assert.equal(calls(),3);assert.equal(x.T.S.answers.size,0);x.close();});
