  const n=await setup();n.T.setFullAuto(true);n.w.document.querySelector('#cur100').classList.remove('posCatalog_active');n.w.document.querySelector('#cur102').classList.add('posCatalog_active');n.store.set(flowStore,record);await n.T.flowBoot();assert(n.T.S.started);assert.equal(n.T.readFlow().phase,'fresh');assert(n.T.S.autoHold==null);assert.deepEqual([...n.T.readFlow().skipped],['100']);n.close();
