const authAccounts='baka.login.accounts.v1',authRequest='baka.login.resume.v1',lockKey='cirno.lock.v5';
function sharedStore(x,store){x.w.GM_getValue=(k,d)=>store.has(k)?store.get(k):d;x.w.GM_setValue=(k,v)=>store.set(k,v);}
function savedLogin(x,enabled=true){x.store.set(authAccounts,{'https://v8.chaoxing.com':{account:'dummy-user',password:'dummy-password',enabled}});let clicks=0;x.w.document.querySelector('#login').onclick=()=>clicks++;return ()=>clicks;}
