await test('manual account or password edits are not overwritten',async()=>{for(const field of ['account','password']){const x=await setup({login:true}),calls=savedLogin(x);x.T.loginForm()[field].value='manual-edit';await x.T.loginTick();assert.equal(calls(),0);assert.equal(x.T.loginForm()[field].value,'manual-edit');x.close();}});
await test('login errors and unaccepted terms prevent retry',async()=>{for(const html of ['<p role="alert">密码错误</p>','<label><input type="checkbox" required>协议</label>']){const x=await setup({login:true}),calls=savedLogin(x);x.w.document.querySelector('form').insertAdjacentHTML('beforeend',html);await x.T.loginTick();assert.equal(calls(),0);x.close();}});
await test('disabled credentials never auto-login and manual retry is bounded',async()=>{const x=await setup({login:true}),calls=savedLogin(x,false);await x.T.loginTick();assert.equal(calls(),0);await x.T.loginTick(true);await x.T.loginTick(true);assert.equal(calls(),1);x.close();});
await test('saved credentials on another origin never fill current form',async()=>{const x=await setup({login:true});x.store.set(authAccounts,{'https://passport2.chaoxing.com':{account:'dummy-user',password:'dummy-password',enabled:true}});await x.T.loginTick();assert.equal(x.T.loginForm().password.value,'');x.close();});
await test('manual pause cancels own auth checkpoint but preserves other page request',async()=>{const x=await setup();x.T.rememberSession(true);x.T.makeAuthRequest();assert(x.T.readAuth());x.T.pause();assert.equal(x.T.readAuth(),null);assert.equal(x.store.get('baka.session.test-tab'),null);x.store.set(authRequest,{owner:'other',url:x.w.location.href,at:Date.now()});x.T.cancelAuthResume();assert(x.T.readAuth());x.close();});
await test('expired resume checkpoint cannot initiate recovery',async()=>{const x=await setup({login:true});x.store.set('baka.session.test-tab',{active:true,url:'https://mooc1.chaoxing.com/mycourse/studentstudy?courseId=c&chapterId=1',at:Date.now()-86400001});assert.equal(x.T.makeAuthRequest(),null);x.close();});
await test('successful login landing returns to recorded chapter only once',async()=>{const x=await setup({login:true});const url='https://mooc1.chaoxing.com/mycourse/studentstudy?courseId=c&chapterId=109';x.store.set(authRequest,{id:'resume',owner:'test-tab',url,at:Date.now(),state:'waiting'});x.w.document.body.innerHTML='<a>我的课程</a><a>退出登录</a>';const moves=[];x.T.recoveryIO.go=u=>moves.push(u);await x.T.authTick();await x.T.authTick();assert.deepEqual(moves,[url]);x.close();});
await test('returning to original chapter restores running state and submission hold',async()=>{const x=await setup();x.T.rememberSession(true);const r=x.T.makeAuthRequest();x.store.set(authRequest,{...r,pendingSubmit:true,state:'entering',targetOwner:'test-tab'});x.T.S.started=false;await x.T.authTick();assert(x.T.S.started);assert(x.T.S.autoHold.submission);assert.equal(x.T.readAuth(),null);assert.equal(x.T.S.calls,0);x.close();});
await test('verification disappearance resumes same chapter without navigation',async()=>{const x=await setup();const b=x.w.document.createElement('div');b.id='captcha';b.textContent='请完成安全验证';x.w.document.body.append(b);const moves=[];x.T.recoveryIO.go=u=>moves.push(u);await x.T.authTick();assert.equal(x.T.S.started,false);b.remove();await x.T.authTick();assert(x.T.S.started);assert.equal(moves.length,0);x.close();});
function correctResult(x,root,answer='B'){const p=x.card.createElement('div');p.className='Py_answer';p.innerHTML='<span>正确答案：</span><span></span><span> 我的答案：A</span>';p.children[1].textContent=answer;root.append(p);return p;}
await test('bank collection is opt-in and never stores merely selected answers',async()=>{const x=await setup(),r=question(x.card,{filled:true}),b=x.w.__BANK;assert.equal(b.collectBank(true),0);correctResult(x,r);assert.equal(b.collectBank(),0);x.T.cfg.collectAnswers=true;assert.equal(b.collectBank(),1);assert.equal(b.bankEntries().length,1);assert.equal(b.bankEntries()[0].answer.choices.join(''),'B');assert.equal(b.collectBank(),0);x.close();});
await test('hidden answer and partial-credit score are not accepted as correct',async()=>{const x=await setup(),r=question(x.card,{filled:true}),b=x.w.__BANK;const p=correctResult(x,r);p.hidden=true;r.insertAdjacentHTML('beforeend','<p>得分：50 我的答案：A</p>');assert.equal(b.collectBank(true),0);x.close();});
await test('bank multi answers retain all labels and ignore student answer',async()=>{const x=await setup(),r=question(x.card,{multi:true}),b=x.w.__BANK;correctResult(x,r,'A、B、C');assert.equal(b.collectBank(true),1);assert.equal(b.bankEntries()[0].answer.choices.join(''),'ABC');x.close();});
await test('bank maps judgment words to visible choices',async()=>{const x=await setup(),r=judgeFixture(x),b=x.w.__BANK;correctResult(x,r,'错');assert.equal(b.collectBank(true),1);assert.equal(b.bankEntries()[0].answer.choices.join(''),'B');x.close();});
await test('bank remaps reordered option content and bypasses API',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;correctResult(x,r);b.collectBank(true);r.querySelector('.Py_answer').remove();const a=r.querySelectorAll('a');a[0].textContent='选项 B';a[1].textContent='选项 A';x.T.cfg.useAnswerBank=true;const answer=await x.T.answer(x.T.parseQuestion(r),x.T.currentEpoch());assert.equal(answer.choices.join(''),'A');assert.equal(x.T.S.calls,0);x.close();});
await test('bank requires identical stem and full option set',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;correctResult(x,r);b.collectBank(true);x.T.cfg.useAnswerBank=true;r.querySelector('.Zy_TItle').textContent='【单选题】测试题不正确的是';assert.equal(b.bankLookup(x.T.parseQuestion(r)),null);r.querySelector('.Zy_TItle').textContent='【单选题】测试题';r.querySelector('a').textContent='变更选项';assert.equal(b.bankLookup(x.T.parseQuestion(r)),null);x.close();});
await test('conflicting official answers are retained but never automatically reused',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;const p=correctResult(x,r);b.collectBank(true);p.children[1].textContent='C';b.collectBank(true);x.T.cfg.useAnswerBank=true;assert.equal(b.bankEntries().length,2);assert.equal(b.bankLookup(x.T.parseQuestion(r)),null);x.close();});
await test('portable export excludes credentials and unrelated settings',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;correctResult(x,r);b.collectBank(true);x.store.set(authAccounts,{'https://v8.chaoxing.com':{account:'private-user',password:'private-password'}});x.T.cfg.profiles.deepseek={key:'private-key'};const exported=b.bankExport();assert(!/private-|apiKey|password|login|https:/.test(exported));assert.deepEqual(Object.keys(JSON.parse(exported)),['format','version','entries']);x.close();});
await test('export import roundtrip merges deduplicates and labels imported provenance',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;correctResult(x,r);b.collectBank(true);const file=b.bankExport(),y=await setup(),c=y.w.__BANK;assert.equal(c.bankImport(file).added,1);assert.equal(c.bankImport(file).added,0);assert.equal(c.bankEntries()[0].source,'imported');y.T.cfg.useAnswerBank=true;assert.equal(c.bankLookup(y.T.parseQuestion(question(y.card))).choices.join(''),'B');x.close();y.close();});
await test('import is atomic when a later entry is malformed',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;correctResult(x,r);b.collectBank(true);const data=JSON.parse(b.bankExport());data.entries.push({...data.entries[0],answer:{choices:['Z'],blanks:[],answer:''}});const y=await setup();assert.throws(()=>y.w.__BANK.bankImport(JSON.stringify(data)),/不匹配/);assert.equal(y.w.__BANK.bankEntries().length,0);assert.throws(()=>b.bankImport('{broken'),/JSON/);assert.throws(()=>b.bankImport('{"format":"other","version":1,"entries":[]}'),/请选择/);x.close();y.close();});
await test('selected export contains only chosen records',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;const p=correctResult(x,r);b.collectBank(true);p.children[1].textContent='C';b.collectBank(true);assert.equal(JSON.parse(b.bankExport(new Set([b.bankEntries()[1].id]))).entries[0].answer.choices.join(''),'C');x.close();});
await test('bank collects while paused after user manually submits',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;x.T.pause();x.T.cfg.collectAnswers=true;correctResult(x,r);await x.T.recoveryTick();assert.equal(b.bankEntries().length,1);assert.equal(x.T.S.started,false);x.close();});
await test('result grace waits for delayed answer then advances without hanging',async()=>{const x=await setup({quiz:true}),r=question(x.card),b=x.w.__BANK;x.T.cfg.collectAnswers=true;x.card.body.insertAdjacentHTML('beforeend','<div class="newAnswerBx">已完成</div>');x.T.advance();assert.equal(x.counts().clicks.length,0);correctResult(x,r);x.T.S.bankWait.at-=3100;x.T.advance();assert.equal(b.bankEntries().length,1);assert.equal(x.counts().clicks.length,1);x.close();});
await test('bank pane persists toggles and selection without rendering imported HTML',async()=>{const x=await setup(),r=question(x.card),b=x.w.__BANK;correctResult(x,r);b.collectBank(true);const data=JSON.parse(b.bankExport());data.entries[0].title='<img src=x onerror=alert(1)>';b.bankImport(JSON.stringify(data));x.T.mount();const root=x.T.ui.root;root.querySelector('[data-tab="bank"]').click();assert.equal(root.querySelector('[data-pane="bank"]').hidden,false);assert.equal(root.querySelector('.bankList img'),null);assert(root.querySelector('.bankList').textContent.includes('<img'));const toggle=root.querySelector('[data-setting="collectAnswers"]');toggle.checked=true;toggle.dispatchEvent(new x.w.Event('change'));assert.equal(x.store.get('cirno.settings.v5').collectAnswers,true);root.querySelector('.bankAll').click();assert.match(root.querySelector('.bankStats').textContent,/已选 2/);x.close();});
await test('bank collects supported blank and text result formats',async()=>{for(const [title,raw,expected] of [['【填空题】补充词语','一；二','一,二'],['【简答题】说明','完整参考答案','完整参考答案']]){const x=await setup(),r=x.card.createElement('div');r.className='TiMu';r.innerHTML='<div class="Zy_TItle"></div>';r.firstChild.textContent=title;x.card.body.append(r);correctResult(x,r,raw);assert.equal(x.w.__BANK.collectBank(true),1);const a=x.w.__BANK.bankEntries()[0].answer;assert.equal(a.blanks.length?a.blanks.join(','):a.answer,expected);x.close();}});
await test('completion marker cannot skip delayed collection during submission',async()=>{const x=await setup({quiz:true}),r=question(x.card);x.T.cfg.collectAnswers=true;x.card.body.insertAdjacentHTML('beforeend','<div class="ans-job-finished"><span class="ans-job-icon" aria-label="任务点已完成"></span></div>');x.T.S.submit={d:x.card,key:x.T.pageKey(),at:Date.now()};x.T.handleSubmission();assert(x.T.S.submit);assert.equal(x.counts().clicks.length,0);correctResult(x,r);x.T.S.bankWait.at-=3100;x.T.handleSubmission();assert.equal(x.w.__BANK.bankEntries().length,1);assert.equal(x.counts().clicks.length,1);x.close();});
await test('image questions never match by text alone',async()=>{const x=await setup(),r=question(x.card);r.insertAdjacentHTML('beforeend','<svg><text>diagram</text></svg>');correctResult(x,r);x.w.__BANK.collectBank(true);x.T.cfg.useAnswerBank=true;assert.equal(x.w.__BANK.bankLookup(x.T.parseQuestion(r)),null);x.close();});
const gradedSamples=JSON.parse(fs.readFileSync(new URL('graded-fixture.json',import.meta.url),'utf8')).filter(s=>s.startsWith('<div'));
function graded(x){x.card.body.innerHTML=gradedSamples.join('\n');return x.w.__BANK;}
await test('synthetic graded result page collects all five questions including optionless judgments',async()=>{const x=await setup(),b=graded(x);assert.equal(b.collectBank(true),5);assert.deepEqual(Array.from(b.bankEntries(),e=>e.answer.choices.join('')),['A','A','A','C','ABC']);assert.equal(b.bankEntries()[0].type,'single');assert.equal(b.bankEntries()[0].options[0].text,'对');x.close();});
await test('wrong partial hidden and conflicting grading marks cannot confirm own answer',async()=>{for(const mode of ['marking_cuo','marking_bandui','hidden','conflict','missing']){const x=await setup(),b=graded(x);for(const e of x.card.querySelectorAll('.marking_dui')){if(mode==='hidden')e.hidden=true;else if(mode==='missing')e.remove();else if(mode==='conflict')e.insertAdjacentHTML('afterend','<span class="marking_bandui"></span>');else e.className=mode;}assert.equal(b.collectBank(true),0,mode);x.close();}});
await test('positive grading from a different question never leaks into another answer',async()=>{const x=await setup(),b=graded(x);x.card.querySelector('.marking_dui').remove();assert.equal(b.collectBank(true),4);assert(!b.bankEntries().some(e=>e.questionId==='700001'));x.close();});
await test('graded judgment can be reused against current true false controls',async()=>{const x=await setup(),b=graded(x);b.collectBank(true);const entry=b.bankEntries()[0];const root=judgeFixture(x),q=x.T.parseQuestion(root);q.title=entry.title;q.id=entry.questionId;q.visual=true;x.T.cfg.useAnswerBank=true;const answer=b.bankLookup(q);assert(answer);assert.equal(answer.choices.join(''),'A');x.close();});
await test('standalone scan works without API or auto collect and does not submit or play',async()=>{const x=await setup({quiz:true}),b=graded(x);const config=JSON.stringify(x.T.cfg);let submits=0;const button=x.card.createElement('button');button.textContent='提交';button.onclick=()=>submits++;x.card.body.append(button);await b.startBankScan();assert.equal(x.T.S.started,false);assert.equal(x.T.cfg.collectAnswers,false);assert.equal(JSON.stringify(x.T.cfg),config);let s=x.T.S.bankScan;s.at-=2100;await b.bankScanTick();assert.equal(s.phase,'result');s.at-=3100;await b.bankScanTick();s.stableAt-=1600;await b.bankScanTick();assert.equal(s.added,5);assert.equal(s.pages,1);assert.equal(submits,0);assert.equal(x.counts().plays,0);assert.equal(x.T.S.calls,0);b.stopBankScan();x.close();});
await test('standalone scan includes completed chapters in catalogue order',async()=>{const x=await setup({quiz:true}),b=x.w.__BANK;await b.startBankScan();const s=x.T.S.bankScan;assert.deepEqual([...s.ids],['100','101','102']);s.phase='cards';s.doneCards=['dct1','dct2'];s.at-=2100;await b.bankScanTick();await b.bankScanTick();assert.equal(s.index,1);assert.equal(x.counts().clicks.at(-1),'cur101');x.close();});
await test('scan waits for replaced card document rather than collecting stale results',async()=>{const x=await setup(),b=graded(x);await b.startBankScan();const s=x.T.S.bankScan;s.at-=2100;await b.bankScanTick();assert.equal(s.phase,'cardWait');x.w.document.querySelector('#dct1').classList.remove('active');x.w.document.querySelector('#dct2').classList.add('active');s.at-=5000;await b.bankScanTick();assert.equal(s.phase,'cardWait');assert.equal(b.bankEntries().length,0);s.at-=31000;await b.bankScanTick();assert.equal(s.phase,'cards');assert.equal(s.skipped,1);x.close();});
await test('scan stops on verification and can resume without enabling normal automation',async()=>{const x=await setup({quiz:true}),b=x.w.__BANK;await b.startBankScan();const el=x.w.document.createElement('div');el.id='captcha';el.textContent='请完成安全验证';x.w.document.body.append(el);await b.bankScanTick();assert.equal(x.T.S.bankScan.active,false);el.remove();await b.startBankScan(true);assert(x.T.S.bankScan.active);assert.equal(x.T.S.started,false);b.stopBankScan();assert.equal(x.store.get(lockKey),null);const count=x.counts().clicks.length;await x.T.recoveryTick();assert.equal(x.counts().clicks.length,count);x.close();});
await test('reload restores paused scan checkpoint and respects another page lease',async()=>{const x=await setup({quiz:true}),b=x.w.__BANK;await b.startBankScan();x.T.S.bankScan.index=1;b.stopBankScan();const saved=x.store.get('baka.bankScan.v1.test-tab');const y=await setup();y.store.set('baka.bankScan.v1.test-tab',saved);y.w.__BANK.restoreBankScan();assert.equal(y.T.S.bankScan.active,false);assert.equal(y.T.S.bankScan.index,1);y.store.set(lockKey,{owner:'other',at:Date.now()});await y.w.__BANK.startBankScan(true);assert.equal(y.T.S.bankScan.active,false);x.close();y.close();});
await test('normal start or pause cancels independent scanning',async()=>{const x=await setup({quiz:true}),b=x.w.__BANK;await b.startBankScan();await x.T.start(false,false,true);assert.equal(x.T.S.bankScan.active,false);assert(x.T.S.started);await b.startBankScan();x.T.pause();assert.equal(x.T.S.bankScan.active,false);assert.equal(x.T.S.started,false);x.close();});
console.log(`${passed} checks passed; no real API calls or live submissions.`);


